// Breadcrumb rendering tests.
//
// The breadcrumb is always exactly Home > Historical Documents > volume title,
// generated by hsg:collection-breadcrumbs() in modules/templates/hsg.xqm.
// Compilation/chapter/document titles are never shown as a crumb -- only as
// the page's own <h1> -- regardless of how deep the current page is.
//
// baseUrl is http://localhost:8080/exist/apps/hsg-jinks (cypress.config.cjs),
// which matches the container's default host port mapping. If you remapped the
// host port (see "Remapping ports" in the README), override it:
// `cypress run --config baseUrl=http://localhost:<host-port>/exist/apps/hsg-jinks`.

const VOLUME = "historicaldocuments/frus1981-88v05";
const VOLUME_TITLE =
    "Foreign Relations of the United States, 1981–1988, Volume V, Soviet Union, March 1985–October 1986";

function crumbTexts() {
    return cy
        .get('nav[aria-label="breadcrumb"] ul:not(:empty) li')
        .then(($lis) => Cypress._.map($lis, (li) => li.textContent.replace(/\s+/g, " ").trim()));
}

describe("breadcrumb", () => {
    it("volume landing page: Home > Historical Documents > volume title (current, not a link)", () => {
        cy.visit(VOLUME);
        crumbTexts().should("deep.equal", ["Home", "Historical Documents", VOLUME_TITLE]);
        cy.get('nav[aria-label="breadcrumb"] ul:not(:empty) li')
            .last()
            .should("have.attr", "aria-current", "page")
            .find("a")
            .should("not.exist");
    });

    [
        ["comp", `${VOLUME}/comp`],
        ["chapter", `${VOLUME}/ch1`],
        ["document", `${VOLUME}/d1`],
    ].forEach(([kind, path]) => {
        it(`${kind} page: same three crumbs, volume title links back to the landing page`, () => {
            cy.visit(path);
            crumbTexts().should("deep.equal", ["Home", "Historical Documents", VOLUME_TITLE]);
            cy.get('nav[aria-label="breadcrumb"] ul:not(:empty) li')
                .last()
                .find("a")
                .should("have.attr", "href")
                .and("match", new RegExp(`/${VOLUME}$`));
        });
    });

    it("Home crumb links to the site root", () => {
        cy.visit(VOLUME);
        cy.get('nav[aria-label="breadcrumb"] ul:not(:empty) li')
            .first()
            .find("a")
            .should("have.attr", "href")
            .and("match", /\/$/);
    });
});
